+/** Theoretical sales use and actual consumption per item for inclusive UTC days. */
+export function varianceReport(store, from, to) {
+  const totals = new Map();
+  const add = (id, field, qty) => {
+    const line = totals.get(id) ?? { itemId: id, theoretical: 0, actual: 0 };
+    line[field] = Math.round((line[field] + qty) * 1000) / 1000;
+    totals.set(id, line);
+  };
+  for (const sale of store.data.sales) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day >= from && day <= to) for (const ingredient of sale.ingredients) add(ingredient.itemId, "theoretical", ingredient.qty);
+  }
+  for (const movement of store.data.movements) {
+    if (movement.type !== "consume" || movement.qty <= 0) continue;
+    const day = new Date(movement.at).toISOString().slice(0, 10);
+    const batch = store.data.batches.find((b) => b.id === movement.batchId);
+    if (batch && day >= from && day <= to) add(batch.itemId, "actual", movement.qty);
+  }
+  return [...totals.values()].filter((line) => line.theoretical > 0 || line.actual > 0)
+    .map((line) => ({ ...line, difference: Math.round((line.actual - line.theoretical) * 1000) / 1000 }))
+    .sort((a, b) => a.itemId - b.itemId);
+}
